UTF8Encoding encoder = new UTF8Encoding(true);
IAsyncResult result = fs.BeginRead(buffer, 0,
buffer.Length, null, null);
Console.WriteLine("Do Something here");
int numBytes = fs.EndRead(result);
fs.Close();
